<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Support\Facades\DB;use Symfony\Component\HttpFoundation\StreamedResponse;
class DatabaseBackupController extends Controller { public function __invoke():StreamedResponse {abort_unless(config('database.default')==='mysql',422,'Database backup is available for MySQL/MariaDB only.');$name='deshibazaar-db-'.now()->format('Ymd-His').'.sql';return response()->streamDownload(function(){ $pdo=DB::connection()->getPdo();echo "-- DeshiBazaar database backup\n-- Generated: ".now()->toIso8601String()."\n\nSET FOREIGN_KEY_CHECKS=0;\n\n";foreach(DB::select('SHOW TABLES') as $row){$table=array_values((array)$row)[0];$create=DB::selectOne("SHOW CREATE TABLE `{$table}`");$definition=array_values((array)$create)[1];echo "DROP TABLE IF EXISTS `{$table}`;\n{$definition};\n\n";foreach(DB::table($table)->cursor() as $record){$values=[];foreach((array)$record as $value){$values[]=$value===null?'NULL':$pdo->quote((string)$value);}echo "INSERT INTO `{$table}` VALUES (".implode(',',$values).");\n";}echo "\n";}echo "SET FOREIGN_KEY_CHECKS=1;\n";},$name,['Content-Type'=>'application/sql','Cache-Control'=>'no-store, private']);}}
